      }
      chord();
      radio.timer = setInterval(chord, pat.tempo * 1000);
    }

    var sounds = {
      shot: function () { noise(0.09, 0.5, 3000); tone(180, 0.08, 'square', 0.15, 60); },
      smg: function () { noise(0.06, 0.35, 2600); },
