      carEnter: function () { tone(300, 0.08, 'square', 0.12); tone(420, 0.1, 'square', 0.12); },
    };

    return {
      ctx: ctx,
      radio: radio,
      play: function (name) {
        try { if (sounds[name]) sounds[name](); } catch (e) {}
      },
      startRadio: startRadio,
      stopRadio: stopRadio,
      nextStation: function () {
        radio.station = (radio.station + 1) % radio.patterns.length;
