          ped.y += Math.sin(ped.angle) * 1.9 * dt * 60 * 0.55;
        } else {
          ped.shootCd -= dt;
          if (ped.shootCd <= 0) {
            SB.enemyShoot(game, ped);
            ped.shootCd = ped.boss ? 0.9 : 1.5;
          }
